class FEMenuEntry
{
    char state[0x60];

public:
    virtual void Load();
    virtual void OnSelect();
    virtual void Highlight(bool h = true, bool anim = true);
    virtual void Disable(bool d = true);
};

class FEMenu
{
    char state_before_parent[0x64];

protected:
    FEMenu *parent;

private:
    char state_after_parent[0x0c];

public:
    virtual void OnActivate();
};

class MainFrontEnd
{
public:
    void ResizeCareerBox(int bottom);
};

struct saveInfo
{
    int type;
    char shortname[8];
    char desc[68];
    long timestamp;
    int valid;
};

extern bool careerStarted;
extern saveInfo currentGame;

class CareerMenu : public FEMenu
{
public:
    enum
    {
        ContinueEntry,
        NewEntry,
        LoadEntry,
        SaveEntry,
        OKEntry,
        CancelEntry,
        NumEntries
    };

    FEMenuEntry *entry[NumEntries];
    void *warning;
    bool warning_up;
    char alignment[3];
    void *sys;
    int warning_bottom;
    int regular_bottom;

    virtual void OnActivate();
};

__asm__(".equ OnActivate__6FEMenu, 0x00157728");
__asm__(".equ ResizeCareerBox__12MainFrontEndi, 0x0017F550");

void CareerMenu::OnActivate()
{
	entry[SaveEntry]->Disable(true);
	entry[OKEntry]->Disable(true);
	entry[CancelEntry]->Disable(true);
	entry[ContinueEntry]->Disable(false);
	entry[LoadEntry]->Disable(false);
	entry[NewEntry]->Disable(false);

	// disable Continue option if no career was loaded
	entry[ContinueEntry]->Disable(!(careerStarted || currentGame.valid == 0));

	// Disable if there are no saved games
	//entry[LoadEntry]->Disable(!((SaveLoadFrontEnd*) manager->gms->menus[GraphicalMenuSystem::SaveLoadMenu])->SavedGamesExist());

	FEMenu::OnActivate();
	//system->manager->em->ToMainScreen();
	warning_up = false;
	((MainFrontEnd*) parent)->ResizeCareerBox(regular_bottom);
}
